import json, pathlib
inp=json.loads(pathlib.Path('/work/inputs/inputs.json').read_text())
def load(mid):
    return json.loads(pathlib.Path(f"/work/inputs/{inp[mid]}").read_text())
cross=load('m_5a9153faeb34')
def val(d):
    return d['value'] if isinstance(d,dict) and 'value' in d else float(d)
def unc(d):
    if isinstance(d,dict):
        u=d.get('uncertainty')
        if isinstance(u,dict): return u.get('value') or 0.0
        if isinstance(u,(int,float)): return float(u)
    return 0.0
cv=val(cross); cu=unc(cross)
stated=10.0
diff=stated-cv
pathlib.Path('/work/outputs').mkdir(parents=True, exist_ok=True)
# diff uncertainty = cu (stated taken as exact reference for this computation; perturbation check is on input cv)
pathlib.Path('/work/outputs/stated_minus_cross.json').write_text(json.dumps({"value": diff, "uncertainty": {"value": cu, "kind": "bound", "method": "uncertainty carried from measured crossing time"}}))
print(cv,cu,diff)
